var e={"maxxing.toggle":`Maxxing`,"maxxing.on":`Maxxing-Modus: Sobald eine Sitzung fertig ist, rückt sie groß nach vorn, damit du sofort das Nächste eintippst`,"maxxing.off":`Der Maxxing-Modus ist aktiv - klicke, um ihn auszuschalten`,"maxxing.next":`Nächste Sitzung`,"maxxing.back":`Zurück`,"maxxing.backTip":`Zurück zur vorherigen Sitzung (ein Prompt, der zu schnell abgeschickt wurde): Sie bleibt vorn, bis du erneut sendest`,"maxxing.waiting":`{n} wartend`,"maxxing.meter.title":`Effizienz`,"maxxing.meter.overdrive":`Overdrive`,"maxxing.meter.utilisation":`Sitzungen bei der Arbeit`,"maxxing.meter.delay":`Durchschnittliche Antwortzeit`,"maxxing.meter.answered":`Neu gestartete Sitzungen`,"maxxing.meter.hint":`Über die letzten 10 Minuten: 70 % die Zeit, in der die Sitzungen arbeiten, 30 % wie schnell du antwortest (Ziel 30 s). Bist du schneller, läuft der Balken über.`};export{e as default};